    assert_receive {:ack, %{"worker_id" => "w-1", "items" => items}}, 1_000
    assert Enum.map(items, & &1["token"]) == ["a", "b", "c"]
  end

  test "a full buffer holds settle/2 until a call takes it, and a 413 is sent in halves",
       %{bypass: bypass, test_pid: test_pid} do
    calls = TestGateway.counter()

    TestGateway.expect(bypass, "POST", "/api/v1/sdk/tasks/ack", fn conn ->
      if TestGateway.tick(calls) == 0 do
        answer(conn, test_pid, 413, ~s({"error":{"code":"too_large","message":"no"}}))
      else
        answer(conn, test_pid, 200, ~s({"results":[]}))
      end
